{
  "name": "@quarkos/pi-fusion",
  "version": "1.0.12",
  "description": "Multi-model deliberation harness (OpenRouter Fusion pattern) for OpenCode Go",
  "main": "index.js",
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./index.js": "./index.js",
    "./package.json": "./package.json"
  },
  "pi": {
    "extensions": [
      "./index.js"
    ]
  },
  "bin": {
    "pi-fusion": "bin/pi-harness.js"
  },
  "files": [
    "bin/",
    "lib/",
    "index.js",
    "pi-harness.config.json",
    "test/",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "start": "node bin/pi-harness.js",
    "test": "node --test test/offline.test.js test/api.test.js",
    "test:stream": "node verify-stream.mjs",
    "test:live": "node verify-harness.js",
    "test:all": "npm test && node verify-stream.mjs && node verify-harness.js",
    "verify:stream": "node verify-stream.mjs"
  },
  "keywords": [
    "pi",
    "harness",
    "fusion",
    "deliberation",
    "opencode",
    "agent",
    "pi-package",
    "llm",
    "multi-model",
    "coding-agent",
    "openrouter"
  ],
  "author": "Antigravity Pair",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/QuarkOS/Pi-Fusion.git"
  },
  "homepage": "https://github.com/QuarkOS/Pi-Fusion#readme",
  "bugs": {
    "url": "https://github.com/QuarkOS/Pi-Fusion/issues"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "chalk": "^5.3.0",
    "commander": "^12.1.0",
    "ora": "^8.0.1"
  },
  "peerDependencies": {
    "@earendil-works/pi-ai": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-ai": {
      "optional": true
    }
  }
}
